PLATFORM_ALIASES: dict[str, list[str]] = {
    "windows-x86_64": ["windows", "win", "win64"],
    "windows-aarch64": ["windows-arm64", "win-arm64"],
    "linux-x86_64": ["linux", "linux64"],
